from collections import Counter

def solve(grid):
    # Determine the background value (most frequent colour)
    flat = [cell for row in grid for cell in row]
    bg = Counter(flat).most_common(1)[0][0]

    rows = len(grid)
    cols = len(grid[0]) if rows else 0

    # Find the bounding box that contains all non‑background cells
    min_r, max_r = rows, -1
    min_c, max_c = cols, -1
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg:
                if r < min_r:
                    min_r = r
                if r > max_r:
                    max_r = r
                if c < min_c:
                    min_c = c
                if c > max_c:
                    max_c = c

    # If there are no non‑background cells, return an empty grid
    if max_r < min_r or max_c < min_c:
        return []

    # Extract the sub‑grid and replace background cells with 0
    out = []
    for r in range(min_r, max_r + 1):
        row = []
        for c in range(min_c, max_c + 1):
            val = grid[r][c]
            row.append(0 if val == bg else val)
        out.append(row)

    return out

